// UI strings for vi + en, compiled by Paraglide JS from `messages/{locale}.json`.
// `src/paraglide/` is generated by `pnpm build`: never edit it.
import { getLocale, locales, type Locale } from './paraglide/runtime.js';

export { m } from './paraglide/messages.js';
export {
  baseLocale,
  getLocale,
  isLocale,
  locales,
  setLocale,
  type Locale,
} from './paraglide/runtime.js';

/** BCP 47 tags for each UI locale, for `Intl` and libraries that want a region (Astryx). */
export const localeTags = { vi: 'vi-VN', en: 'en-US' } as const satisfies Record<Locale, string>;

/** The active locale's BCP 47 tag. */
export const getLocaleTag = () => localeTags[getLocale()];

export const isSupportedLocale = (value: string): value is Locale =>
  (locales as ReadonlyArray<string>).includes(value);
